public class ComparadorEdades {
    public static void main(String[] args) {
        int edad1 = 25;
        int edad2 = 70;

        boolean puedeVotar1 = edad1 >= 18;
        boolean puedeVotar2 = edad2 >= 18;
        boolean ambosVotan = puedeVotar1 && puedeVotar2;
        boolean algunoMayor65 = edad1 > 65 || edad2 > 65;
        boolean mismaEdad = edad1 == edad2;

        System.out.println("Person 1 can vote: " + puedeVotar1);
        System.out.println("Person 2 can vote: " + puedeVotar2);
        System.out.println("Both can vote: " + ambosVotan);
        System.out.println("Someone over 65: " + algunoMayor65);
        System.out.println("Same age: " + mismaEdad);
    }
}

